<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tempo — To-do List</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&display=swap" rel="stylesheet"><style>
:root{--g:#f2f4f7;--s:#fff;--b:#e2e5e9;--r:#edf0f2;--t:#101214;--m:#5f6873;--p:#16191d;--blue:#1d5fbf;--bad:#b42328;--ok:#216d47;font-family:Geist,system-ui,sans-serif;color:var(--t)}*{box-sizing:border-box}body{margin:0;background:var(--g);font-size:14px}button,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #8cb8f5;outline-offset:2px}[hidden]{display:none!important}.auth{min-height:100vh;display:grid;place-items:center;padding:20px}.auth-card,.panel{background:var(--s);border:1px solid var(--b);border-radius:8px}.auth-card{width:min(100%,430px);padding:32px}.brand{display:flex;align-items:center;gap:9px;font-size:18px;font-weight:600}.mark{display:grid;place-items:center;width:27px;height:27px;border-radius:7px;background:var(--t);color:#fff}.auth h1{font-size:24px;margin:40px 0 6px}.intro,.sub,.copy{margin:0 0 24px;color:var(--m)}.field{display:grid;gap:7px;margin:0 0 15px}label{font-weight:500}input{height:40px;width:100%;border:1px solid #cdd2d8;border-radius:6px;padding:0 11px}.btn{min-height:36px;padding:0 13px;border:1px solid transparent;border-radius:6px;font-weight:500}.primary{background:var(--p);color:#fff}.secondary{background:#fff;border-color:#cdd2d8}.text{border:0;background:none;padding:0;color:var(--t);font-weight:600;text-decoration:underline}.auth .btn{width:100%;margin-top:6px}.switch{text-align:center;color:var(--m);margin:22px 0 0}.message{min-height:18px;margin:0 0 10px;color:var(--bad);font-size:12px}.app{min-height:100vh;display:grid;grid-template-columns:256px minmax(0,1fr)}.side{padding:28px 12px 16px;display:flex;flex-direction:column;border-right:1px solid var(--b)}.space{padding:9px 10px;margin:24px 0 30px;background:#e9ecef;border-radius:6px;font-weight:500}.nav-title{margin:0 10px 10px;color:var(--m);font-size:12px}.nav{height:34px;width:100%;border:0;border-radius:6px;padding:0 10px;background:none;color:var(--m);text-align:left}.nav:hover,.nav.active{background:#e5e8eb;color:var(--t)}.bottom{margin-top:auto}.user{display:flex;gap:9px;align-items:center;padding:12px 10px}.avatar{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#dfe6ef;color:#314a6d;font-weight:600}.email{font-size:12px;color:var(--m)}main{padding:34px 40px 56px;min-width:0}.head,.panel-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.head{margin-bottom:26px}h1{margin:0;font-size:24px;letter-spacing:-.02em}.sub{margin:7px 0 0}.actions{display:flex;gap:8px;align-items:center}.updated{font-size:12px;color:var(--m)}.summary{display:grid;grid-template-columns:repeat(3,1fr);background:var(--s);border:1px solid var(--b);border-radius:8px;margin-bottom:24px}.metric{padding:17px 20px}.metric+.metric{border-left:1px solid var(--b)}.metric small{color:var(--m)}.metric strong{display:block;font-size:28px;font-weight:500;margin-top:3px;font-variant-numeric:tabular-nums}.grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:12px;align-items:start}.panel-head{padding:18px 20px 14px;align-items:center}.panel h2{font-size:16px;margin:0}.filters{display:flex;padding:3px;gap:3px;background:#eef0f2;border-radius:6px}.filter{border:0;background:transparent;border-radius:4px;padding:5px 8px;color:var(--m);font-size:12px}.filter.active{background:#fff;color:var(--t)}.tasks{padding:0 12px 12px}.task{display:grid;grid-template-columns:20px minmax(0,1fr) auto auto auto;gap:12px;align-items:center;min-height:62px;padding:9px 8px;border-radius:6px}.task+.task{border-top:1px solid var(--r)}.task:hover{outline:1px solid var(--b)}.check{appearance:none;width:18px;height:18px;border:1.5px solid #89919b;border-radius:50%;margin:0}.check:checked{background:var(--t);border-color:var(--t);box-shadow:inset 0 0 0 4px #fff}.title{font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.done .title{text-decoration:line-through;color:var(--m)}time{font-size:12px;color:var(--m);white-space:nowrap}.late{color:var(--bad)}.action-btn{height:28px;padding:0 10px;border:0;border-radius:5px;background:none;color:var(--m);font-size:12px;font-weight:500}.action-btn:hover{background:#eef0f2}.delete-btn:hover{color:var(--bad)}.side-panel{padding:20px}.side-panel+.side-panel{margin-top:12px}.copy{font-size:13px;margin:6px 0 16px}.deadlines{padding:0;margin:0;list-style:none}.deadlines li{display:flex;justify-content:space-between;gap:10px;min-height:40px;align-items:center;border-top:1px solid var(--r)}.deadlines li:first-child{border:0}.deadlines span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.empty,.loading,.error{padding:34px 20px;text-align:center;color:var(--m)}.error{color:var(--bad)}.toast{position:fixed;right:24px;bottom:24px;padding:11px 14px;border-radius:6px;background:var(--t);color:#fff;opacity:0;transform:translateY(8px);transition:.18s}.toast.show{opacity:1;transform:none}.backdrop{position:fixed;inset:0;display:grid;place-items:center;padding:20px;background:#10121455}.modal{width:min(100%,440px);background:#fff;border-radius:8px;padding:24px}.modal h2{margin:0 0 20px;font-size:18px}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}@media(max-width:900px){.app{grid-template-columns:1fr}.side{display:none}main{padding:24px}.grid{grid-template-columns:1fr}.side-panel+.side-panel{margin-top:0}}@media(max-width:600px){main{padding:20px 16px 40px}.head{display:block}.actions{margin-top:14px}.summary{grid-template-columns:1fr 1fr}.metric:last-child{grid-column:1/-1;border-top:1px solid var(--b)}.metric+.metric{border-left:0}.metric:nth-child(2){border-left:1px solid var(--b)}.task{grid-template-columns:20px minmax(0,1fr) auto auto}.task time{grid-column:2/5;grid-row:2;margin-top:4px}.task .action-btn{grid-row:1;font-size:11px;padding:0 8px;height:24px}}
</style></head><body>
<section class="auth" id="auth"><div class="auth-card"><div class="brand"><span class="mark">✓</span>Tempo</div><form id="login"><h1>Masuk ke ruang kerja</h1><p class="intro">Kelola pekerjaanmu dalam satu daftar yang tenang.</p><p class="message" id="login-msg" aria-live="polite"></p><div class="field"><label for="l-email">Email</label><input id="l-email" type="email" value="nabila@example.com" required></div><div class="field"><label for="l-pass">Kata sandi</label><input id="l-pass" type="password" value="password" required></div><button class="btn primary">Masuk</button><p class="switch">Belum punya akun? <button type="button" class="text" data-auth="register">Buat akun</button></p></form><form id="register" hidden><h1>Buat akun baru</h1><p class="intro">Mulai susun tugas yang penting untukmu.</p><p class="message" id="reg-msg" aria-live="polite"></p><div class="field"><label for="r-name">Nama</label><input id="r-name" required></div><div class="field"><label for="r-email">Email</label><input id="r-email" type="email" required></div><div class="field"><label for="r-pass">Kata sandi</label><input id="r-pass" type="password" minlength="8" required></div><button class="btn primary">Buat akun</button><p class="switch">Sudah punya akun? <button type="button" class="text" data-auth="login">Masuk</button></p></form></div></section>
<section class="app" id="dashboard" hidden><aside class="side"><div class="brand"><span class="mark">✓</span>Tempo</div><div class="space">Ruang pribadi</div><p class="nav-title">Pekerjaan</p><button class="nav active">☷ &nbsp; Semua tugas</button><button class="nav" data-nav="todo">○ &nbsp; Belum selesai</button><button class="nav" data-nav="done">✓ &nbsp; Selesai</button><div class="bottom"><button class="nav" id="logout">↪ &nbsp; Keluar</button><div class="user"><span class="avatar" id="initial">N</span><div><div id="name">Nabila</div><div class="email" id="email">nabila@example.com</div></div></div></div></aside><main><header class="head"><div><h1>Tugas saya</h1><p class="sub" id="finding">Memuat tugas…</p></div><div class="actions"><span class="updated" id="updated"></span><button class="btn primary" id="add">Tambah tugas</button></div></header><section class="summary"><div class="metric"><small>Total tugas</small><strong id="total">—</strong></div><div class="metric"><small>Belum selesai</small><strong id="todo">—</strong></div><div class="metric"><small>Selesai</small><strong id="done">—</strong></div></section><div class="grid"><section class="panel"><header class="panel-head"><h2>Daftar tugas</h2><div class="filters"><button class="filter active" data-filter="all">Semua</button><button class="filter" data-filter="todo">Belum selesai</button><button class="filter" data-filter="done">Selesai</button></div></header><div class="tasks" id="tasks" aria-live="polite"><div class="loading">Memuat tugas…</div></div></section><aside><section class="panel side-panel"><h2>Tambah tugas cepat</h2><p class="copy">Tulis yang perlu dikerjakan, lalu atur tenggatnya.</p><form id="quick"><div class="field"><label for="q-title">Judul tugas</label><input id="q-title" required placeholder="Contoh: Kirim revisi desain"></div><div class="field"><label for="q-date">Tenggat</label><input id="q-date" type="date" required></div><button class="btn primary">Simpan tugas</button></form></section><section class="panel side-panel"><h2>Tenggat terdekat</h2><ul class="deadlines" id="deadlines"><li>Memuat…</li></ul></section></aside></div></main></section><div class="toast" id="toast" role="status"></div>
<template id="modal-tpl"><div class="backdrop"><form class="modal" id="editor"><h2 id="modal-title">Tambah tugas</h2><div class="field"><label for="e-title">Judul tugas</label><input id="e-title" required></div><div class="field"><label for="e-date">Tenggat</label><input id="e-date" type="date" required></div><p class="message" id="edit-msg"></p><div class="modal-actions"><button type="button" class="btn secondary" id="delete" hidden>Hapus</button><button type="button" class="btn secondary" id="cancel">Batal</button><button class="btn primary">Simpan</button></div></form></div></template>
<script>
const api={useMock:true,baseUrl:'/api',token:localStorage.getItem('tempo.token')||null},key='tempo.mock.tasks',$=s=>document.querySelector(s);let tasks=[],filter='all',editId=null;
const clean=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));const date=d=>{if(!d)return'—';const iso=d.includes('T')?d:d+'T00:00:00Z';return new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date(iso))};const late=t=>t.status==='todo'&&t.deadline&&t.deadline.split('T')[0]<new Date().toISOString().slice(0,10);const save=()=>localStorage.setItem(key,JSON.stringify(tasks));function notice(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}
async function request(path,opts={}){if(api.useMock){if(path==='/tugas'&&(!opts.method||opts.method==='GET')){const cached=localStorage.getItem(key);if(cached)return JSON.parse(cached);const r=await fetch('/mock/tasks.json');if(!r.ok)throw Error('Mock tidak dapat dimuat.');const data=await r.json();localStorage.setItem(key,JSON.stringify(data));return data}if(path==='/login'&&opts.method==='POST'){return {user:{id:'mock_1',name:opts.body.email.split('@')[0],email:opts.body.email},token:'mock_token_'+Date.now()}}if(path==='/register'&&opts.method==='POST'){return {user:{id:'mock_2',name:opts.body.username,email:opts.body.email}}}if(path.startsWith('/tugas/')&&opts.method==='DELETE'){const id=path.split('/')[2];tasks=tasks.filter(t=>t.id!==id);save();return {success:true}}if(path.startsWith('/tugas/')&&opts.method==='PUT'){const id=path.split('/')[2];const task=tasks.find(t=>t.id===id);if(task)Object.assign(task,opts.body);save();return task}if(path==='/tugas'&&opts.method==='POST'){const newTask={id:'task_'+Date.now(),...opts.body};tasks.unshift(newTask);save();return newTask}if(path==='/logout'){return {success:true}}return null}const r=await fetch(api.baseUrl+path,{...opts,headers:{Accept:'application/json','Content-Type':'application/json',...(api.token?{Authorization:`Bearer ${api.token}`}:{})},...(opts.body?{body:JSON.stringify(opts.body)}:{})}),data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.message||'Permintaan gagal.');return data.data||data}
function render(){const list=tasks.filter(t=>filter==='all'||t.status===filter),todo=tasks.filter(t=>t.status==='todo').length;$('#total').textContent=tasks.length;$('#todo').textContent=todo;$('#done').textContent=tasks.length-todo;$('#finding').textContent=todo?`${todo} tugas belum selesai. Pilih satu yang ingin kamu tuntaskan hari ini.`:'Semua tugas sudah selesai. Tambahkan langkah berikutnya saat siap.';$('#updated').textContent='Diperbarui '+new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit'}).format(new Date());$('#tasks').innerHTML=list.length?list.map(t=>`<article class="task ${t.status==='done'?'done':''}"><input class="check" type="checkbox" data-toggle="${t.id}" ${t.status==='done'?'checked':''} aria-label="Ubah status ${clean(t.title)}"><div class="title">${clean(t.title)}</div><time class="${late(t)?'late':''}">${late(t)?'Lewat ':''}${date(t.deadline)}</time><button class="action-btn" data-edit="${t.id}" aria-label="Ubah ${clean(t.title)}">Ubah</button><button class="action-btn delete-btn" data-delete="${t.id}" aria-label="Hapus ${clean(t.title)}">Hapus</button></article>`).join(''):'<div class="empty">Tidak ada tugas di daftar ini.<br><button class="text" id="empty-add">Tambah tugas</button></div>';const up=tasks.filter(t=>t.status==='todo').sort((a,b)=>a.deadline.localeCompare(b.deadline)).slice(0,3);$('#deadlines').innerHTML=up.length?up.map(t=>`<li><span>${clean(t.title)}</span><time>${date(t.deadline)}</time></li>`).join(''):'<li>Tak ada tenggat aktif.</li>';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter))}
function openModal(t=null){editId=t?.id||null;document.body.append($('#modal-tpl').content.cloneNode(true));$('#modal-title').textContent=t?'Ubah tugas':'Tambah tugas';$('#e-title').value=t?.title||'';const deadlineValue=t?.deadline?t.deadline.split('T')[0]:new Date().toISOString().slice(0,10);$('#e-date').value=deadlineValue;$('#e-title').focus();$('#cancel').onclick=closeModal;if(t){$('#delete').hidden=false;$('#delete').onclick=async()=>{try{await request(`/tugas/${editId}`,{method:'DELETE'});tasks=tasks.filter(item=>item.id!==editId);closeModal();render();notice('Tugas dihapus.')}catch(e){$('#edit-msg').textContent=clean(e.message)}}}$('.backdrop').onclick=e=>{if(e.target.classList.contains('backdrop'))closeModal()};$('#editor').onsubmit=async e=>{e.preventDefault();const title=$('#e-title').value.trim(),deadline=$('#e-date').value;if(!title||!deadline){$('#edit-msg').textContent='Judul dan tenggat wajib diisi.';return}const payload={title,deadline:deadline+'T23:59:59Z',status:t?.status||'todo'};try{if(editId){const updated=await request(`/tugas/${editId}`,{method:'PUT',body:payload});Object.assign(tasks.find(x=>x.id===editId),updated);notice('Tugas diperbarui.')}else{const created=await request('/tugas',{method:'POST',body:payload});tasks.unshift(created);notice('Tugas ditambahkan.')}closeModal();render()}catch(e){$('#edit-msg').textContent=clean(e.message)}}}function closeModal(){$('.backdrop')?.remove()}
async function load(){try{tasks=await request('/tugas');render()}catch(e){$('#tasks').innerHTML=`<div class="error">${clean(e.message)}<br><button class="text" id="retry">Coba lagi</button></div>`;$('#retry').onclick=load}}
function signIn(user,token){sessionStorage.setItem('tempo.user',JSON.stringify(user));localStorage.setItem('tempo.token',token);api.token=token;$('#name').textContent=user.name;$('#email').textContent=user.email;$('#initial').textContent=user.name[0].toUpperCase();$('#auth').hidden=true;$('#dashboard').hidden=false;load()}function switchAuth(mode){$('#login').hidden=mode!=='login';$('#register').hidden=mode!=='register'}
document.addEventListener('click',e=>{const a=e.target.closest('[data-auth]');if(a)switchAuth(a.dataset.auth);const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render()}const n=e.target.closest('[data-nav]');if(n){filter=n.dataset.nav;render()}const edit=e.target.closest('[data-edit]');if(edit)openModal(tasks.find(t=>t.id===edit.dataset.edit));const del=e.target.closest('[data-delete]');if(del){if(confirm('Hapus tugas ini?')){const id=del.dataset.delete;request(`/tugas/${id}`,{method:'DELETE'}).then(()=>{tasks=tasks.filter(t=>t.id!==id);render();notice('Tugas dihapus.')}).catch(err=>notice('Gagal menghapus tugas.'))}}const toggle=e.target.closest('[data-toggle]');if(toggle){const t=tasks.find(x=>x.id===toggle.dataset.toggle);const newStatus=toggle.checked?'done':'todo';request(`/tugas/${t.id}`,{method:'PUT',body:{title:t.title,deadline:t.deadline,status:newStatus}}).then(updated=>{Object.assign(t,updated);render();notice(t.status==='done'?'Tugas ditandai selesai.':'Tugas dibuka kembali.')}).catch(err=>{toggle.checked=!toggle.checked;notice('Gagal mengubah status.')})}if(e.target.id==='empty-add')openModal()});$('#add').onclick=()=>openModal();$('#quick').onsubmit=async e=>{e.preventDefault();const title=$('#q-title').value.trim(),deadline=$('#q-date').value;if(!title||!deadline)return;try{const created=await request('/tugas',{method:'POST',body:{title,deadline:deadline+'T23:59:59Z',status:'todo'}});tasks.unshift(created);e.target.reset();render();notice('Tugas ditambahkan.')}catch(err){notice('Gagal menambahkan tugas.')}};$('#login').onsubmit=async e=>{e.preventDefault();const email=$('#l-email').value.trim(),pass=$('#l-pass').value;if(!email||!pass){$('#login-msg').textContent='Email dan kata sandi wajib diisi.';return}try{const res=await request('/login',{method:'POST',body:{email,password:pass}});if(!res||!res.user||!res.token){throw Error('Format respons tidak sesuai.')}signIn(res.user,res.token)}catch(err){$('#login-msg').textContent=clean(err.message)}};$('#register').onsubmit=async e=>{e.preventDefault();const name=$('#r-name').value.trim(),email=$('#r-email').value.trim(),pass=$('#r-pass').value;if(!name||!email||pass.length<8){$('#reg-msg').textContent='Isi semua data. Kata sandi minimal 8 karakter.';return}try{await request('/register',{method:'POST',body:{username:name,email,password:pass,password_confirmation:pass}});$('#reg-msg').textContent='';switchAuth('login');notice('Akun dibuat. Silakan masuk.')}catch(err){$('#reg-msg').textContent=clean(err.message)}};$('#logout').onclick=async()=>{try{await request('/logout',{method:'POST'})}catch(e){}sessionStorage.removeItem('tempo.user');localStorage.removeItem('tempo.token');api.token=null;$('#dashboard').hidden=true;$('#auth').hidden=false;switchAuth('login')};const user=sessionStorage.getItem('tempo.user');const token=localStorage.getItem('tempo.token');if(user&&token){const u=JSON.parse(user);api.token=token;$('#name').textContent=u.name;$('#email').textContent=u.email;$('#initial').textContent=u.name[0].toUpperCase();$('#auth').hidden=true;$('#dashboard').hidden=false;load()}
</script></body></html>
